\label{defsemihey}

	A \emph{semi-Heyting algebra} is an algebra $\mathbf{H}=\langle H; \land,\lor,\Rightarrow,0,1 \rangle$ of type $(2,2,2,0,0)$ such that the following conditions are satisfied for all $x,y,z\in A$:

	\begin{enumerate}[(SH1)]
		\item $\langle H,\land,\lor,0,1 \rangle$ is a bounded lattice,
		\item $x\land(x\Rightarrow y)=x\land y$, \label{infimoeimplicaSH}
		\item $x\land(y\Rightarrow z)=x\land((x\land y)\Rightarrow(x\land z))$, \label{meterinfimoadentrodeimplicaSH}
		\item $x\Rightarrow x=1$. \label{autoimplicaSH}
	\end{enumerate}

	A semi-Heyting algebra is a \emph{Heyting algebra} if it satisfies the identity:
	\begin{enumerate}
	    \item [(H)] $(x\land y)\Rightarrow x=1$.
	\end{enumerate}

\label{defnel}

	A \emph{Nelson algebra} is an algebra $\mathbf{A}=\langle A; \land,\lor,\to,\sim,1 \rangle$ of type $(2,2,2,1,0)$ such that the following conditions are satisfied for all $x,y,z\in A$:

	\begin{enumerate}[(N1)]
		\item $x\land(x\lor y)=x$, \label{primercondicretN}
		\item $x\land(y\lor z)=(z\land x)\lor(y\land x)$, \label{segundacondicretN}
		\item $\sim\sim x=x$, \label{involucionN}
		\item $\sim(x\land y)=\sim x\lor \sim y$, \label{deMenInfN}
		\item $x\land \sim x=(x\land \sim x)\land (y\lor \sim y)$, \label{kleeneN}
		\item $x\to x=1$, \label{ximpxigual1N}
		\item $x\to(y\to z)=(x\land y)\to z$, \label{relacImplicaInf2N}
		\item $x\land (x\to y)=x\land(\sim x\lor y)$. \label{relacImplicaInfN}
	\end{enumerate}

\label{defseminel}
A \emph{semi-Nelson algebra} is an algebra $\mathbf{A}=\langle A; \land, \lor,\to, \sim, 1 \rangle$ of type $(2,2,2,1,0)$ such that the following conditions are satisfied for all $x,y,z\in A$:

    \begin{enumerate}[(SN1)]
    	\item $x\land(x\lor y)=x$, \label{identidad_absorc}
    	\item $x\land(y\lor z)=(z\land x) \lor(y\land x)$, \label{identidad_distrib_inf}
    	\item $\sim\sim x=x$, \label{identidad_doble_neg}
    	\item $\sim(x\land y)=\sim x\lor\sim y$, \label{identidad_ditrib_neg}
    	\item $x\land\sim x=(x\land\sim x)\lor(y\lor\sim y)$, \label{identidad_kleene}
    	\item $x\land(x\mbox{$\ \to_\text {\tiny N}\ $} y)=x\land(\sim x\lor y)$, \label{identidad_implic_negacion}
    	\item $x\mbox{$\ \to_\text {\tiny N}\ $}(y\mbox{$\ \to_\text {\tiny N}\ $} z)=(x\land y)\mbox{$\ \to_\text {\tiny N}\ $} z$, \label{identidad_implica_infimo}
    	\item $(x\mbox{$\ \to_\text {\tiny N}\ $} y)\mbox{$\ \to_\text {\tiny N}\ $}[(y\mbox{$\ \to_\text {\tiny N}\ $} x)\mbox{$\ \to_\text {\tiny N}\ $}[(x\to z)\mbox{$\ \to_\text {\tiny N}\ $}(y\to z)]]=1$,                                 
    	\item $(x\mbox{$\ \to_\text {\tiny N}\ $} y)\mbox{$\ \to_\text {\tiny N}\ $}[(y\to_N x)\mbox{$\ \to_\text {\tiny N}\ $}[(z\to x)\mbox{$\ \to_\text {\tiny N}\ $}(z\to y)]]=1$,                                   
    	\item $(\sim(x\to y))\mbox{$\ \to_\text {\tiny N}\ $}(x\land\sim y)  =  1$,\label{identidad_semi_neg_implica_impl}
    	\item $(x\land\sim y)\mbox{$\ \to_\text {\tiny N}\ $}(\sim(x\to y))  =  1$,\label{identidad_semi_impl_implica_neg}
    \end{enumerate}
where $x \mbox{$\ \to_\text {\tiny N}\ $} y := x \to (x \land y)$.

\label{defdualsemiheyting}
An algebra $\mathbf{A}=\langle A; \land,\lor,\to,^\dagger,0,1 \rangle$ of type $(2,2,2,1,0,0)$ is said to be a \emph{dually hemimorphic semi-Heyting algebra} if $\langle A; \land,\lor,\to,0,1 \rangle$ is a semi-Heyting algebra and the following equations are satisfied:

\begin{enumerate}[DSM1)]
    \item $0^\dagger=1$,\label{op_tilde_0}
    \item $1^\dagger=0$,\label{op_tilde_1}
    \item $(x\land y)^\dagger=x^\dagger\lor y^\dagger$.\label{distib_tilde_inf}
\end{enumerate}

\label{defdualseminelson}
An algebra $\mathbf{A}=\langle A; \land,\lor,\to,\sim,',1 \rangle$ of type $(2,2,2,1,0)$ is said to be a \emph{dually hemimorphic semi-Nelson algebra} if $\langle A; \land,\lor,\to,\sim,1 \rangle$ is a semi-Nelson algebra and the following equations are satisfied:

\begin{enumerate}[DSN1)]
    \item $(\sim 1)'=1$,\label{dhsn_1}
    \item $1'\to(\sim1)=1$,\label{dhsn_2}
    \item $((x\to y)\land(y\to x)\land x')\to((x\to y)\land(y\to x)\land y)'=1$,\label{dhsn_3}
    \item $\sim x'\to(\sim x\land(x'\to x))=1$,\label{dhsn_4}
    \item $(\sim x\land(x'\to x))\to\sim x'=1$,\label{dhsn_5}
    \item $(x\land y)'\to(x'\lor y')=1$,\label{dhsn_6}
    \item $(x'\lor y')\to(x\land y)'=1$.\label{dhsn_7}
\end{enumerate}

We use the convention that the unary operation $'$ has higher priority than $\sim$, so the expression $\sim x'$ means $\sim(x')$.

\label{propertiesseminelson} {\rm \cite[Lemma 2.7 (h) and (l)]{cornejo16semiNelson}}
Let $\mathbf{A}\in\mbox{$\cal SN$}$, and $a,b,c\in A$. Then the following properties hold:
\begin{enumerate}[(1)]
    \item $a\mbox{$\ \to_\text {\tiny N}\ $} b=b\mbox{$\ \to_\text {\tiny N}\ $} a=1$ if and only if $a\to b=b\to a=1$,\label{equivalenciadeclasesnelson}
    \item If $a\mbox{$\ \to_\text {\tiny N}\ $} b=1=b\mbox{$\ \to_\text {\tiny N}\ $} c=1$, then $a\mbox{$\ \to_\text {\tiny N}\ $} c=1$.\label{transitivitynelson}
\end{enumerate}

\label{ejemplofiltronoifiltro}
	Consider the semi-Heyting algebra $\mathbf{A}=\langle A; \land,\lor,$ $\Rightarrow,1 \rangle$, with the operation $\Rightarrow$ indicated in the table:
	\vspace{2mm}

	\begin{minipage}{7cm}
		\begin{center}
			\setlength\unitlength{1mm}

			\begin{picture}(70,40)(10,-10)

			\put(45,20){\circle{2}}
 			\put(45,0){\circle{2}}


			\put(50,0){\makebox(0,0){$0$}}
			\put(50,20){\makebox(0,0){$1$}}


			\put(45,1){\line(0,1){18}}

			\put(35,20){$A$}
			\end{picture}
		\end{center}
	\end{minipage}
	\begin{minipage}{3cm}
		\begin{center}
			\begin{tabular}{c||c|c}
				$\Rightarrow$&$0$&$1$\\\hline\hline
				$0$&$1$&$0$\\ \hline
				$1$&$0$&$1$
			\end{tabular}
		\end{center} 
	\end{minipage}

The subset $F=\{1\}$ of $\mathbf A$ is a filter, and it satisfies $IF2)$ (since the only dense element is 1). But $F$ does not satisfy $IF3$) because $1\lor 0=1\in F$, but $(0\Rightarrow 1)\lor(0\land0)=0\lor0=0\notin F$.

